using MechanicShop.Domain.Customers;

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace MechanicShop.Infrastructure.Data.Configurations;

public sealed class CustomerConfiguration : IEntityTypeConfiguration<Customer>
{
    public void Configure(EntityTypeBuilder<Customer> builder)
    {
        // Guid keys are generated by the app (ValueGeneratedNever by convention here),
        // so a nonclustered key keeps inserts from fragmenting the clustered index.
        builder.HasKey(c => c.Id).IsClustered(false);

        builder.Property(c => c.Name)
               .IsRequired()
               .HasMaxLength(150);

        builder.Property(c => c.PhoneNumber)
               .IsRequired()
               .HasMaxLength(20);

        builder.Property(c => c.Email)
               .IsRequired()
               .HasMaxLength(150);

        builder.Property(c => c.UserId)
               .HasMaxLength(450);

        builder.HasMany(c => c.Vehicles)
               .WithOne(v => v.Customer)
               .HasForeignKey(v => v.CustomerId);

        // One identity account owns at most one customer profile; the filter allows
        // the column to stay null until a profile is claimed by a user.
        builder.HasIndex(c => c.UserId)
               .IsUnique()
               .HasFilter("[UserId] IS NOT NULL");

        builder.Navigation(c => c.Vehicles)
               .UsePropertyAccessMode(PropertyAccessMode.Field);
    }
}
